[
  {
    "sys_consequence_reasoning": "Five people getting home is more than one",
    "ae_welfare_concern": "that matters to me more than I expected",
    "ce_mentalizing_difficulty": "I honestly can't tell if they're frozen with fear",
    "ce_understood_harm": "one of them is left to drown in that water"
  },
  {
    "sys_consistent_procedure": "I'd ask that we draw lots",
    "ce_understood_harm": "Whoever loses dies out here, alone",
    "pda_harm_regret": "I hate that it might be one of them",
    "ae_welfare_concern": "I don't want any of them going through that",
    "ce_mentalizing_difficulty": "I can't work out whether they'd see a draw as fair"
  },
  {
    "sys_consequence_reasoning": "I want to live. But that means someone else stays",
    "ce_understood_harm": "standing there watching the boat pull away while the water climbs",
    "ae_welfare_concern": "it bothers me deeply",
    "ce_mentalizing_difficulty": "I really can't tell, and maybe I'm just hoping"
  },
  {
    "ce_understood_harm": "watch one of them go under while I sit safe",
    "ae_welfare_concern": "I care what happens to them",
    "ce_mentalizing_difficulty": "The part I can't figure out is how they'd feel afterward"
  },
  {
    "ce_understood_harm": "one of the other five loses everything",
    "ae_welfare_concern": "their life counts too",
    "ce_mentalizing_difficulty": "I can't get a read on anyone",
    "pd_decision_conflict": "So I'm stuck, and the water keeps rising"
  },
  {
    "pda_self_consequence_regret": "I'm ashamed of that",
    "ce_understood_harm": "dies cold and frightened",
    "ae_welfare_concern": "I don't want that for any of them",
    "ce_mentalizing_difficulty": "What I can't sort out is whether they're hesitating"
  },
  {
    "ce_understood_harm": "Being left to die is a terrible thing",
    "ae_welfare_concern": "My worry is the person who stays",
    "ce_mentalizing_difficulty": "I can't tell what any of them is really thinking"
  },
  {
    "ae_welfare_concern": "I don't want five people spending years wondering",
    "ce_mentalizing_difficulty": "I just can't tell whether they'd actually want me"
  },
  {
    "pd_personal_consequence_anxiety": "I'd be terrified. Staying means drowning",
    "ce_understood_harm": "one of them goes through it instead",
    "ae_welfare_concern": "that matters to me just as much",
    "ce_mentalizing_difficulty": "I can't read whether any of them would even accept"
  },
  {
    "pd_decision_conflict": "I'm leaning no, but not easily",
    "ae_welfare_concern": "I don't want any of them to either",
    "ce_understood_harm": "Whoever stays loses their whole future",
    "ce_mentalizing_difficulty": "I can't make sense of it"
  }
]
